    v.reserve(5);
    if (v.capacity() != 5 || v.size() != 2 || g_frees != 1 || v.start[0].x0 != 1.0f || v.start[0].y1 != 4.0f || v.start[1].x1 != 7.0f) {
        std::printf("00a74940_TEST FAIL\n"); return 1;
    }
